// CollectionsRiskSchema.js — FRONTEND schema: labels, formulas, remarks, click-throughs. Generated by gen-report.js from report.map (same folder).
// The numbers come from the backend twin app/api/mda4/reports/collections/risk/list/CollectionsRiskSchema.js (same measure keys).
import { getApiRoutes } from '../../../AppRoutes/apiRoutesHandler';
import CollectionsRiskActions from './logicControl/actionsRegistry';
const apiRoutes = getApiRoutes();

export const CollectionsRiskSchema = {
  entity: 'simukopa_collections_risk',
  label: 'Contract Risk Score',
  description: '',
  apiBase: apiRoutes.collectionsrisk?.base,
  moduleRole: 'view_reports',
  currency: 'KES',
  actionRegistry: CollectionsRiskActions,

  groupBy: 'loan',
  groupLabel: 'Contract',
  sortBy: 'score desc',

  fields: [
    { key: 'late', label: 'Overdue Installments', from: 'loan_installments' },
    { key: 'late_amount', label: 'Overdue Amount', from: 'loan_installments.balance_amount', type: 'money' },
    { key: 'penalties', label: 'Penalties', from: 'loan_installments.penalty_amount', type: 'money' },
    { key: 'actions', label: 'Follow-ups', from: 'collection_actions' },
    { key: 'promised', label: 'Promised', from: 'collection_actions.promise_amount', type: 'money' },
    { key: 'lateness_pts', label: 'Lateness Points', calc: 'min(late, 4) * 2' },
    { key: 'chase_pts', label: 'No Follow-up Points', calc: 'min(late, 1) * (1 - min(actions, 1)) * 3' },
    { key: 'penalty_pts', label: 'Penalty Points', calc: 'min(round(penalties / 1000), 2)' },
    { key: 'score', label: 'Risk Score', calc: 'lateness_pts + chase_pts + penalty_pts' },
  ],

  remarks: [
    { if: 'score >= 9', tone: 'bad', title: 'High risk', say: '{label} scores {score}: {late} overdue installments worth {late_amount}, {actions} follow-ups.' },
    { if: 'score >= 4', tone: 'watch', title: 'Medium risk', say: '{label} scores {score}: {late} overdue installments worth {late_amount}.' },
    { if: 'true', tone: 'good', title: 'Low risk', say: '{label} scores {score} and has little or nothing overdue.' },
  ],

  headline: '{label} carries the highest risk: score {score} with {late_amount} overdue.',
};
